// Obtener todos los items de entrada
const items = $input.all();
const results = [];

for (const item of items) {
  const audioBase64 = item.json.mensajeAudio;
  const audioDuration = item.json.audioDuration || 0;

  // Validar que existe el audio
  if (!audioBase64 || audioBase64.length === 0) {
    throw new Error('No se recibió audio en mensajeAudio');
  }

  // Validar tamaño mínimo (al menos 100 caracteres de base64)
  if (audioBase64.length < 100) {
    throw new Error(`Audio demasiado corto: ${audioBase64.length} caracteres. Puede estar vacío o corrupto.`);
  }

  // Validar que sea base64 válido (caracteres permitidos)
  const base64Regex = /^[A-Za-z0-9+/]+=*$/;
  if (!base64Regex.test(audioBase64)) {
    throw new Error('El audio no tiene formato base64 válido');
  }

  // Calcular tamaño aproximado en bytes
  const audioSizeBytes = Math.floor(audioBase64.length * 0.75);

  console.log('===== Audio Conversion =====');
  console.log('Audio base64 length:', audioBase64.length);
  console.log('Audio size (bytes):', audioSizeBytes);
  console.log('Audio duration (seconds):', audioDuration);
  console.log('Audio base64 preview:', audioBase64.substring(0, 50) + '...');
  console.log('Audio base64 end:', '...' + audioBase64.substring(audioBase64.length - 50));
  console.log('============================');

  // Crear el objeto con binary data
  results.push({
    json: {
      ...item.json,
      audioSize: audioSizeBytes,
      audioValid: true
    },
    binary: {
      audio: {
        data: audioBase64,
        mimeType: 'audio/webm',
        fileName: `recording_${audioDuration}s.webm`
      }
    }
  });
}

return results;

// Convertir audio de ElevenLabs a Base64
// En n8n, los datos binarios ya vienen en base64 en el campo 'data'

const responseText = $('Merge Responses').item.json.aiResponse;

// Verificar si hay datos binarios
if (!items[0].binary || !items[0].binary.data) {
  throw new Error('No se encontró audio en la respuesta de ElevenLabs');
}

// Obtener el base64 del audio (ya está en base64 en n8n)
const audioBase64Raw = items[0].binary.data.data;

// Agregar prefijo de data URI para audio
const audioBase64 = `data:audio/mpeg;base64,${audioBase64Raw}`;

console.log('Audio obtenido:', {
  hasAudio: true,
  audioLength: audioBase64Raw ? audioBase64Raw.length : 0,
  preview: audioBase64Raw ? audioBase64Raw.substring(0, 50) + '...' : 'N/A'
});

return {
  json: {
    text: responseText,
    hasAudio: true,
    audioBase64: audioBase64
  }
};

// Formatear respuesta del AI Agent preservando todos los campos originales
const aiOutput = $json.output || $json.text || '';

return {
  json: {
    ...$json,
    aiResponse: aiOutput,
    category: $json.category || "general"
  }
};

// Limpiar texto para Text-to-Speech (ElevenLabs)
// Elimina emojis, markdown, y caracteres especiales que ElevenLabs no puede pronunciar

const rawText = $('Merge Responses').item.json.aiResponse || '';

// 1. Eliminar emojis y símbolos Unicode
let cleanedText = rawText.replace(/[\u{1F600}-\u{1F64F}]/gu, ''); // Emoticonos
cleanedText = cleanedText.replace(/[\u{1F300}-\u{1F5FF}]/gu, ''); // Símbolos y pictogramas
cleanedText = cleanedText.replace(/[\u{1F680}-\u{1F6FF}]/gu, ''); // Transporte
cleanedText = cleanedText.replace(/[\u{1F1E0}-\u{1F1FF}]/gu, ''); // Banderas
cleanedText = cleanedText.replace(/[\u{2600}-\u{26FF}]/gu, '');   // Símbolos misc
cleanedText = cleanedText.replace(/[\u{2700}-\u{27BF}]/gu, '');   // Dingbats
cleanedText = cleanedText.replace(/[\u{FE00}-\u{FE0F}]/gu, '');   // Selectores
cleanedText = cleanedText.replace(/[\u{1F900}-\u{1F9FF}]/gu, ''); // Suplementarios
cleanedText = cleanedText.replace(/[\u{1FA00}-\u{1FA6F}]/gu, ''); // Extendidos A
cleanedText = cleanedText.replace(/[\u{1FA70}-\u{1FAFF}]/gu, ''); // Extendidos B

// 2. Limpiar formato Markdown
cleanedText = cleanedText.replace(/^#{1,6}\s+(.+)$/gm, '$1');      // Encabezados
cleanedText = cleanedText.replace(/\*\*(.+?)\*\*/g, '$1');         // Negrita
cleanedText = cleanedText.replace(/__(.+?)__/g, '$1');             // Negrita alternativa
cleanedText = cleanedText.replace(/\*(.+?)\*/g, '$1');             // Cursiva
cleanedText = cleanedText.replace(/_(.+?)_/g, '$1');               // Cursiva alternativa
cleanedText = cleanedText.replace(/^[\-\*]\s+/gm, '');             // Listas
cleanedText = cleanedText.replace(/^\d+\.\s+/gm, '');              // Listas numeradas
cleanedText = cleanedText.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1'); // Links
cleanedText = cleanedText.replace(/`([^`]+)`/g, '$1');             // Código inline
cleanedText = cleanedText.replace(/```[\s\S]*?```/g, '');          // Bloques de código

// 3. Limpiar caracteres especiales problemáticos
cleanedText = cleanedText.replace(/[•●○◆◇■□▪▫]/g, '');  // Viñetas
cleanedText = cleanedText.replace(/[→←↑↓↔]/g, '');      // Flechas
cleanedText = cleanedText.replace(/[©®™]/g, '');        // Símbolos legales

// 4. Limpiar espacios múltiples y saltos de línea excesivos
cleanedText = cleanedText.replace(/\n{3,}/g, '\n\n');  // Máximo 2 saltos
cleanedText = cleanedText.replace(/\s{2,}/g, ' ');      // Espacios múltiples
cleanedText = cleanedText.trim();

// 5. Reemplazar algunos símbolos con palabras
cleanedText = cleanedText.replace(/&/g, 'y');
cleanedText = cleanedText.replace(/@/g, 'arroba');
cleanedText = cleanedText.replace(/%/g, 'por ciento');

console.log('Texto limpiado para TTS:', {
  original: rawText.substring(0, 100),
  cleaned: cleanedText.substring(0, 100),
  originalLength: rawText.length,
  cleanedLength: cleanedText.length
});

return {
  json: {
    ...$json,
    cleanedTextForTTS: cleanedText
  }
};

// Limpiar memoria conversacional
// Este nodo se ejecuta cuando el usuario solicita borrar el historial

const sessionId = $json.sessionId;

console.log('🧹 Limpiando memoria para sesión:', sessionId);

// Retornar mensaje de confirmación
return {
  json: {
    success: true,
    data: {
      response: "✅ **Historial limpiado**\n\nLa conversación ha sido reiniciada. ¿En qué puedo ayudarte? 😊",
      audio: null,
      hasAudio: false,
      memoryCleared: true
    }
  }
};

// Classify-Source v3 - WhatsApp SOLO por @s.whatsapp.net
const input = $input.first().json;
const body = input.body || input;

const EVOLUTION_API_URL = 'https://wa.miclickderecho.com';
const EVOLUTION_INSTANCE = 'ibon-p';

function getRemoteJid(b) {
  try {
    if (b && b.data && b.data.key && b.data.key.remoteJid) {
      return String(b.data.key.remoteJid);
    }
  } catch(e) {}
  return '';
}

const remoteJid = getRemoteJid(body);
const instance = body.instance || '';

// Detectores
const isWhatsAppJid = remoteJid.indexOf('@s.whatsapp.net') !== -1;
const isWebJid = remoteJid.indexOf('@web.ibon.net') !== -1;
const isWebInstance = instance.indexOf('Web') !== -1;

// Mapeo de instancia Web a proyecto
function getProjectFromInstance(inst) {
  if (inst.indexOf('IbonLanding') !== -1) return 'ibon-landing';
  if (inst.indexOf('RetoGluteos') !== -1) return 'reto-gluteos';
  if (inst.indexOf('PalacioFitness') !== -1) return 'palacio-fitness';
  if (inst.indexOf('ByIbon') !== -1) return 'by-ibon';
  return null;
}

const debug = {
  remoteJid: remoteJid,
  instance: instance,
  isWhatsAppJid: isWhatsAppJid,
  isWebJid: isWebJid,
  isWebInstance: isWebInstance
};

let source = {
  platform: 'unknown',
  project: null,
  component: null,
  url: null,
  isWhatsApp: false,
  isWeb: false,
  phoneNumber: null,
  instance: instance,
  evolutionUrl: EVOLUTION_API_URL,
  evolutionInstance: EVOLUTION_INSTANCE
};

// 1. WhatsApp: SOLO si remoteJid tiene @s.whatsapp.net
if (isWhatsAppJid) {
  source.platform = 'whatsapp';
  source.project = 'whatsapp';
  source.isWhatsApp = true;
  source.phoneNumber = remoteJid.replace('@s.whatsapp.net', '');
  source.instance = EVOLUTION_INSTANCE;
  debug.detected = 'WHATSAPP';
}
// 2. Web con campo origin (formato antiguo)
else if (body.origin && body.origin.platform === 'web') {
  source.platform = 'web';
  source.project = body.origin.project;
  source.component = body.origin.component;
  source.url = body.origin.url;
  source.isWeb = true;
  debug.detected = 'WEB-ORIGIN';
}
// 3. Web por instancia (IbonLandingWeb, RetoGluteosWeb, etc)
else if (isWebInstance || isWebJid) {
  source.platform = 'web';
  source.project = getProjectFromInstance(instance);
  source.isWeb = true;
  debug.detected = 'WEB-INSTANCE';
}
else {
  debug.detected = 'UNKNOWN';
}

return [{ json: { body: body, source: source, headers: input.headers, _debug: debug } }];

// Input: fecha como string YYYY-MM-DD
// La variable 'query' contiene el input del AI

let fecha = query;

// Si viene como JSON, parsearlo
try {
  const parsed = JSON.parse(query);
  fecha = parsed.fecha || parsed;
} catch(e) {
  // Es string directo, usar tal cual
}

// Validar formato
if (!fecha || typeof fecha !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
  return JSON.stringify({ error: "Formato invalido. Usa YYYY-MM-DD", recibido: fecha });
}

// Llamar API usando this.helpers.httpRequest de n8n
const response = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://ibonpalacio.com/api/check-availability.php?fecha=${fecha}`,
  json: true
});

return JSON.stringify(response);

// Input: JSON string con datos de la cita
// La variable 'query' contiene el input del AI

let input;
try {
  input = JSON.parse(query);
} catch(e) {
  return JSON.stringify({ success: false, error: "Input debe ser JSON valido", recibido: query });
}

// Validar campos requeridos
const required = ['nombre', 'correo', 'telefono', 'fecha', 'hora', 'asunto'];
const missing = required.filter(f => !input[f]);

if (missing.length > 0) {
  return JSON.stringify({
    success: false,
    error: "Faltan campos: " + missing.join(", "),
    campos_recibidos: Object.keys(input)
  });
}

// Llamar API usando this.helpers.httpRequest de n8n
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://ibonpalacio.com/api/send-email.php',
  headers: { 'Content-Type': 'application/json' },
  body: {
    nombre: input.nombre,
    correo: input.correo,
    telefono: input.telefono,
    fecha: input.fecha,
    hora: input.hora,
    asunto: input.asunto,
    origen: input.origen || 'chat'
  },
  json: true
});

return JSON.stringify(response);

// Combinar datos de Set-Combined-Data con Instructions y FAQs (obtenidos por HTTP Request nodes)
const origData = $('Set-Combined-Data').first().json;

// Leer instrucciones del HTTP Request node Fetch-Instructions
const instrResponse = $('Fetch-Instructions').first().json;
const instructions = instrResponse.instructions || {};

// Leer FAQs del HTTP Request node Fetch-FAQs
const faqsResponse = $('Fetch-FAQs').first().json;
const faqs = faqsResponse.faqs || [];

// Formatear FAQs como texto
const faqsText = faqs.map(f => `P: ${f.q}\nR: ${f.a}`).join('\n\n');

return [{
  json: {
    ...origData,
    instr_personalidad: instructions.instr_personalidad || '',
    instr_negocio: instructions.instr_negocio || '',
    instr_situaciones: instructions.instr_situaciones || '',
    instr_protocolo: instructions.instr_protocolo || '',
    instr_herramientas: instructions.instr_herramientas || '',
    faqs: faqsText
  }
}];

